namespace optiling {

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    GemmGroupNormSwishMultiplySwishCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0);        // [B, K]
    const gert::Shape* w_shape = context->GetInputShape(1);        // [N, K]
    uint32_t B = static_cast<uint32_t>(x_shape->GetDim(0));
    uint32_t K = static_cast<uint32_t>(x_shape->GetDim(1));
    uint32_t N = static_cast<uint32_t>(w_shape->GetDim(0));

    // Try get num_groups from op attribute if provided; fallback: equal to N (equivalent to LayerNorm per channel group size 1)
    uint32_t num_groups = N;
    auto attrs = context->GetAttrs();
    if (attrs != nullptr && attrs->HasAttr("num_groups")) {
        num_groups = static_cast<uint32_t>(attrs->GetAttrInt("num_groups"));
    }

    float epsilon = 1e-5f;
    if (attrs != nullptr && attrs->HasAttr("eps")) {
        epsilon = static_cast<float>(attrs->GetAttrFloat("eps"));
    }

    // Decide blockDim using platform helper when available
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());
    auto aicNum = ascendcPlatform.GetCoreNumAic();
    auto aivNum = ascendcPlatform.GetCoreNumAiv();
    uint32_t sliceNum = aivNum > 0 ? aivNum : 8;
    uint32_t blockDim = ascendcPlatform.CalcTschBlockDim(sliceNum, aicNum, aivNum);
    if (blockDim == 0) { blockDim = 8; }

    uint32_t tileNum = 8; // simple constant tiling

    context->SetBlockDim(blockDim);

    tiling.set_batch(B);
    tiling.set_inFeatures(K);
    tiling.set_outFeatures(N);
    tiling.set_numGroups(num_groups);
    tiling.set_tileNum(tileNum);
    tiling.set_blockDim(blockDim);
    tiling.set_epsilon(epsilon);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

